mapper.select:
select f.id, f.sn, f.home_latitude as lat, f.home_longitude as lng, f.start_time as startTime from flights f
f.home_latitude is not null and f.home_longitude is not null and f.user_id = #{userId}
order by f.start_time desc limit 100

select f.sn, d.model, coalesce(sum(f.duration), 0) as flyTime from flights f left join devices d on f.sn = d.sn
and f.user_id = #{userId}
group by f.sn, d.model order by flyTime desc limit 10
